import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"@jsprismarine/console-protocol","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/console-protocol/index.md","filePath":"api/@jsprismarine/console-protocol/index.md"}`),a={name:`api/@jsprismarine/console-protocol/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../">JSPrismarine</a> / @jsprismarine/console-protocol</p><h1 id="jsprismarine-console-protocol" tabindex="-1">@jsprismarine/console-protocol <a class="header-anchor" href="#jsprismarine-console-protocol" aria-label="Permalink to “@jsprismarine/console-protocol”">​</a></h1><p><a href="https://discord.gg/6w8JWhy" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/704967868885762108?color=%237289DA&amp;label=Discord" alt="Join the Discord Server"></a><a href="https://www.npmjs.com/package/@jsprismarine/console-protocol" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/@jsprismarine/console-protocol" alt="npm"></a></p><p>Message types and links between the JSPrismarine server and its console.</p><p>When the server runs under the terminal UI it is a child process, and the two sides talk over Node&#39;s IPC channel. This package defines what they say to each other and how a message gets from one side to the other. It depends only on <code>@jsprismarine/logger</code> (for <code>LogLevel</code>), so neither the server nor the host pulls in a renderer by importing it.</p><p>There are three message families. <code>ServerMessage</code> is everything the server sends: <code>hello</code> on connect, <code>log</code> records with a sequence number and <code>log.dropped</code> when the server had to shed records, <code>status</code> with TPS, player count, memory, and uptime, <code>lifecycle</code> state changes, and <code>command.result</code> and <code>complete.result</code> replies. <code>ConsoleMessage</code> is what the console sends back: <code>command</code>, <code>complete</code>, <code>subscribe</code> to set the log level, and <code>shutdown</code>. <code>SupervisorEvent</code> never crosses the channel; the host raises it for the UI to describe its own state (watching, a changed path, regenerating data, a restart, raw child output).</p><p>A <code>MessageLink&lt;In, Out&gt;</code> is the channel itself: <code>send</code>, <code>onMessage</code>, <code>onClose</code>, <code>close</code>. <code>send</code> returns <code>false</code> when the channel asks the sender to slow down. Three adapters implement it: <code>childProcessLink()</code> on the server side over <code>process.send</code>, <code>subprocessLink(child)</code> on the host side over the spawned child, and <code>memoryLinkPair()</code> for tests. <code>isServerMessage</code> and <code>isConsoleMessage</code> check that incoming JSON has one of the known shapes before you trust it.</p><h2 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to “Exports”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Kind</th></tr></thead><tbody><tr><td><code>PROTOCOL_VERSION</code></td><td>constant, currently <code>1</code>; every message carries it as <code>v</code></td></tr><tr><td><code>ServerMessage</code>, <code>ServerMessageType</code>, <code>LogEntry</code>, <code>LifecycleState</code></td><td>types for the server side</td></tr><tr><td><code>ConsoleMessage</code>, <code>ConsoleMessageType</code></td><td>types for the console side</td></tr><tr><td><code>SupervisorEvent</code>, <code>SupervisorState</code></td><td>types for host-local events</td></tr><tr><td><code>isServerMessage</code>, <code>isConsoleMessage</code></td><td>type guards</td></tr><tr><td><code>MessageLink</code>, <code>LinkOptions</code></td><td>the channel interface and adapter options</td></tr><tr><td><code>childProcessLink</code>, <code>subprocessLink</code>, <code>memoryLinkPair</code></td><td>adapters</td></tr><tr><td><code>ChildProcessLink</code>, <code>ChildProcessLinkOptions</code>, <code>IpcProcess</code></td><td>types for the server-side adapter</td></tr></tbody></table><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to “Interfaces”">​</a></h2><ul><li><a href="./interfaces/ChildProcessLink.html">ChildProcessLink</a></li><li><a href="./interfaces/ChildProcessLinkOptions.html">ChildProcessLinkOptions</a></li><li><a href="./interfaces/IpcProcess.html">IpcProcess</a></li><li><a href="./interfaces/LinkOptions.html">LinkOptions</a></li><li><a href="./interfaces/LogEntry.html">LogEntry</a></li><li><a href="./interfaces/MessageLink.html">MessageLink</a></li></ul><h2 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to “Type Aliases”">​</a></h2><ul><li><a href="./type-aliases/ConsoleMessage.html">ConsoleMessage</a></li><li><a href="./type-aliases/ConsoleMessageType.html">ConsoleMessageType</a></li><li><a href="./type-aliases/IpcChild.html">IpcChild</a></li><li><a href="./type-aliases/LifecycleState.html">LifecycleState</a></li><li><a href="./type-aliases/ServerMessage.html">ServerMessage</a></li><li><a href="./type-aliases/ServerMessageType.html">ServerMessageType</a></li><li><a href="./type-aliases/SupervisorEvent.html">SupervisorEvent</a></li><li><a href="./type-aliases/SupervisorState.html">SupervisorState</a></li></ul><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><ul><li><a href="./variables/LIFECYCLE_STATES.html">LIFECYCLE_STATES</a></li><li><a href="./variables/PROTOCOL_VERSION.html">PROTOCOL_VERSION</a></li></ul><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><ul><li><a href="./functions/childProcessLink.html">childProcessLink</a></li><li><a href="./functions/isConsoleMessage.html">isConsoleMessage</a></li><li><a href="./functions/isLifecycleState.html">isLifecycleState</a></li><li><a href="./functions/isServerMessage.html">isServerMessage</a></li><li><a href="./functions/memoryLinkPair.html">memoryLinkPair</a></li><li><a href="./functions/subprocessLink.html">subprocessLink</a></li></ul>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};